// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Adopt and discard in the editor"
// Changes: Store tests for adopting a draft part by part: safety snapshot of the project labelled after the draft,
//          chosen parts written (export naming and simulation inputs untouched), final snapshot, the draft ends as
//          adopted; refused when the project moved past the revision the human saw; undone by restoring the safety snapshot.

import { beforeEach, describe, expect, it } from 'vitest'
import { readParts } from '#/lib/parts'
import { defaultProjectData, type ProjectData } from '#/lib/project'
import { openDatabase } from './db.server'
import { createProjectStore, type ProjectStore } from './projects.server'

const MINUTE = 60_000

let time: number
let store: ProjectStore
const advance = (ms: number) => {
  time += ms
}

beforeEach(() => {
  time = Date.parse('2026-01-01T10:00:00.000Z')
  store = createProjectStore(openDatabase(':memory:'), { now: () => new Date(time) })
})

const expressions = (): ProjectData => ({
  ...defaultProjectData(),
  def: { nonterminals: 'E', terminals: 'id +', start: 'E' },
  ll: { grammar: 'E -> id', input: 'id + id' },
  prec: { terminals: ['+', 'id'], cells: { 'id\u0001+': '>' }, rules: 'E -> E + E', input: 'id' },
  names: { map: 'id ID', ntPrefix: 'N_', tPrefix: 'T_', precPrefix: 'P_' },
})

/** A project with a draft whose grammar rules and reduction rules an agent changed. */
function changedDraft() {
  const project = store.createProject('Výrazy', expressions())
  const draft = store.createDraft(project.id, 'Oprava', 'agent')!
  store.editDraft(draft.id, { grammarRules: 'E -> id + E', reductionRules: 'E -> id' }, { author: 'agent' })
  advance(MINUTE)
  return { project, draft: store.getDraft(draft.id)! }
}

describe('adopting a draft', () => {
  it('writes only the chosen parts into the project and bumps its revision; export naming and inputs stay', () => {
    const { project, draft } = changedDraft()

    const result = store.adoptDraft(draft.id, ['grammarRules'], project.revision)

    expect(result.status).toBe('adopted')
    const adopted = store.getProject(project.id)!
    expect(adopted.revision).toBe(project.revision + 1)
    expect(adopted.updatedAt).toBe('2026-01-01T10:01:00.000Z')
    expect(adopted.data).toEqual({ ...expressions(), ll: { grammar: 'E -> id + E', input: 'id + id' } })
    expect(result).toMatchObject({ project: adopted })
  })

  it("keeps the project's previous state as a safety snapshot labelled after the draft", () => {
    const { project, draft } = changedDraft()
    store.adoptDraft(draft.id, ['grammarRules', 'reductionRules'], project.revision)

    const [safety] = store.listSnapshots(project.id)
    expect(safety).toMatchObject({ kind: 'safety', label: 'Pred prevzatím návrhu „Oprava“' })
    expect(store.getSnapshot(safety.id)!.data).toEqual(expressions())
  })

  it("ends the draft as adopted with a final snapshot of its last state in the draft's history", () => {
    const { project, draft } = changedDraft()
    const result = store.adoptDraft(draft.id, ['grammarRules'], project.revision)

    const ended = store.getDraft(draft.id)!
    expect(ended).toMatchObject({ state: 'adopted', endedAt: '2026-01-01T10:01:00.000Z', parts: draft.parts })
    expect(result).toMatchObject({ draft: ended })
    const [final] = store.listDraftSnapshots(draft.id)
    expect(final).toMatchObject({ kind: 'final', label: 'Prevzatý návrh „Oprava“' })
    expect(readParts(store.getSnapshot(final.id)!.data)).toEqual(draft.parts)
    expect(store.listProjects()[0].openDrafts).toBe(0)
  })

  it('an adopted draft is read-only and cannot be adopted or discarded again', () => {
    const { project, draft } = changedDraft()
    store.adoptDraft(draft.id, ['grammarRules'], project.revision)
    const after = store.getProject(project.id)!

    expect(store.editDraft(draft.id, { grammarRules: 'E -> x' }, { author: 'human' })).toMatchObject({ status: 'ended' })
    expect(store.adoptDraft(draft.id, ['reductionRules'], after.revision)).toMatchObject({ status: 'ended' })
    expect(store.discardDraft(draft.id)).toMatchObject({ status: 'ended' })
    expect(store.getProject(project.id)).toEqual(after)
    expect(store.listDraftSnapshots(draft.id).filter((s) => s.kind === 'final')).toHaveLength(1)
  })

  it('is refused when the project moved past the revision the human saw; nothing changes', () => {
    const { project, draft } = changedDraft()
    store.saveProject(project.id, { ...expressions(), def: { ...expressions().def, start: 'S' } }, project.revision)
    const moved = store.getProject(project.id)!

    const result = store.adoptDraft(draft.id, ['grammarRules'], project.revision)

    expect(result).toEqual({ status: 'stale', project: moved, draft })
    expect(store.getProject(project.id)).toEqual(moved)
    expect(store.getDraft(draft.id)).toEqual(draft)
    expect(store.listSnapshots(project.id).filter((s) => s.kind === 'safety')).toEqual([])
  })

  it('needs at least one part; an unknown draft is missing', () => {
    const { project, draft } = changedDraft()
    expect(() => store.adoptDraft(draft.id, [], project.revision)).toThrow()
    expect(store.getDraft(draft.id)!.state).toBe('open')
    expect(store.adoptDraft('nope', ['grammarRules'], 1)).toEqual({ status: 'missing' })
  })

  it("restoring the safety snapshot from the project's history undoes the adoption", () => {
    const { project, draft } = changedDraft()
    store.adoptDraft(draft.id, ['grammarRules', 'reductionRules'], project.revision)
    const safety = store.listSnapshots(project.id).find((s) => s.kind === 'safety')!

    store.restoreSnapshot(project.id, safety.id)

    expect(store.getProject(project.id)!.data).toEqual(expressions())
  })
})
